public static class F1DetailPreview {
 static string Out=>Path.GetFullPath(Application.dataPath+"/../../../Docs/Review/2026-11-13_1F_DetailPass/");static Scene preview;
 static float[] V(Vector3 v)=>new[]{v.x,v.y,v.z};
 public static object Run(){var active=SceneManager.GetActiveScene();bool dirty=active.isDirty;bool playing=Application.isPlaying;string path=active.path;preview=EditorSceneManager.OpenPreviewScene("Assets/Afrer_Seconds/01.Scenes/Stage/Level_1F_Factory.unity");object result;
 try{var ts=preview.GetRootGameObjects().SelectMany(g=>g.GetComponentsInChildren<Transform>(true)).ToArray();var map=ts.ToDictionary(t=>AnimationUtility.CalculateTransformPath(t,null));var before=JArray.Parse(File.ReadAllText(Out+"before_transforms.json"));var changes=new List<string>();foreach(var b in before){string p=(string)b["path"];if(!map.TryGetValue(p,out var t)){changes.Add(p+" missing");continue;}foreach(var q in new[]{new{key="position",value=V(t.position)},new{key="local",value=V(t.localPosition)},new{key="rotation",value=V(t.localEulerAngles)},new{key="scale",value=V(t.localScale)}}){var vals=b[q.key].Values<float>().ToArray();if(q.value.Where((v,i)=>Mathf.Abs(v-vals[i])>.00001f).Any())changes.Add(p+" "+q.key);}if((bool)b["active"]!=t.gameObject.activeSelf)changes.Add(p+" active");}
 var state=ts.Select(t=>new{path=AnimationUtility.CalculateTransformPath(t,null),position=V(t.position),local=V(t.localPosition),rotation=V(t.localEulerAngles),scale=V(t.localScale),active=t.gameObject.activeSelf,colliders=t.GetComponents<Collider>().Select(c=>new{type=c.GetType().Name,enabled=c.enabled}).ToArray()}).ToArray();File.WriteAllText(Out+"after_transforms.json",JsonConvert.SerializeObject(state,Formatting.Indented));
 var attachmentErrors=new List<string>();var instances=JArray.Parse(File.ReadAllText(Out+"apply.json"));foreach(var q in instances){string p=(string)q["parent"]+"/"+(string)q["name"];if(!map.TryGetValue(p,out var t)){attachmentErrors.Add(p+" missing");continue;}if(t.localPosition!=Vector3.zero||t.localRotation!=Quaternion.identity||t.localScale!=Vector3.one)attachmentErrors.Add(p+" offset");if((bool)q["dynamic"]&&t.GetComponentsInChildren<Transform>().Any(a=>GameObjectUtility.GetStaticEditorFlags(a.gameObject)!=0))attachmentErrors.Add(p+" static");}
 var shader=AssetDatabase.LoadAssetAtPath<Shader>("Assets/Afrer_Seconds/05.Model/Environment/1F/AEWeatheredLit.shader");var messages=ShaderUtil.GetShaderMessages(shader).Select(m=>new{m.message,severity=m.severity.ToString(),m.line}).ToArray();var lodErrors=ts.SelectMany(t=>t.GetComponents<LODGroup>()).Where(g=>g.GetLODs().Any(l=>l.renderers.Any(r=>!r))).Select(g=>g.name).ToArray();
 Directory.CreateDirectory(Out+"after");Shot("Warmup",new Vector3(-8,1.2f,-15.5f),new Vector3(-7.5f,1.2f,-14.14f),63);Shot("Wall",new Vector3(-8,1.2f,-15.5f),new Vector3(-7.5f,1.2f,-14.14f),63);Shot("Facade",new Vector3(-15,2.4f,-22),new Vector3(-12,4.5f,-14),72);Shot("Ivy",new Vector3(-28,1.7f,-36),new Vector3(-29,1.4f,-33),65);Shot("Lift",new Vector3(43.2f,1.7f,25.5f),new Vector3(44,1.5f,29),78);Shot("Hoist",new Vector3(45.5f,6.4f,26.35f),new Vector3(42.8f,5.8f,28.4f),78);Shot("LiftControl",new Vector3(44.2f,1.70f,27.1f),new Vector3(45.64f,1.65f,27.53f),60);
 foreach(string kind in new[]{"Press","ConveyorLong","Forklift","PartsRack","Switchgear","CableReel","OfficeDesk_A","MotorBench","ToolCart","KitchenCounter"}){var t=ts.FirstOrDefault(x=>x.name.StartsWith("F1_")&&x.name.Contains("_"+kind+"_")&&!x.name.EndsWith("_Chair"));if(!t)continue;var rr=t.GetComponentsInChildren<Renderer>().Where(r=>r.name.EndsWith("LOD0")&&!r.name.StartsWith("FD_")).ToArray();if(rr.Length==0)rr=t.GetComponentsInChildren<Renderer>().Where(r=>!r.name.StartsWith("FD_")).ToArray();if(rr.Length==0)continue;var bounds=rr[0].bounds;foreach(var r in rr)bounds.Encapsulate(r.bounds);float d=Mathf.Max(bounds.size.x,bounds.size.y,bounds.size.z);Shot(kind,bounds.center+t.TransformDirection(new Vector3(-.48f,.3f,1.05f))*Mathf.Clamp(d*1.4f,1.1f,5.5f),bounds.center,58);}
 var lift=ts.Single(t=>t.name=="F1_VL_LiftAssembly");var car=lift.Find("Car");var weight=lift.Find("Counterweight");var wheel=lift.Find("Sheave");var ca=car.Find("FD_LiftCar");var cw=weight.Find("FD_LiftCounterweight");var fixedPart=lift.Find("FixedShaft/FD_LiftGuides");var ca0=ca.position;var cw0=cw.position;var fixed0=fixedPart.position;var car0=car.localPosition;var weight0=weight.localPosition;var rotation0=wheel.localRotation;car.localPosition+=Vector3.down*9;weight.localPosition+=Vector3.up*9;wheel.localRotation=Quaternion.Euler(0,0,90);var movement=new{carFollow=Vector3.Distance(ca.position,ca0+Vector3.down*9)<.0001f,counterweightFollow=Vector3.Distance(cw.position,cw0+Vector3.up*9)<.0001f,wheelFollow=Quaternion.Angle(wheel.rotation,wheel.Find("FD_LiftSheave").rotation)<.001f,fixedStayed=fixedPart.position==fixed0,previewOnly=true,runtimeScriptsAdded=0};car.localPosition=car0;weight.localPosition=weight0;wheel.localRotation=rotation0;File.WriteAllText(Out+"moving_parts.json",JsonConvert.SerializeObject(movement,Formatting.Indented));
 result=new{scene=preview.path,isolatedPreview=true,beforeTransforms=before.Count,transforms=ts.Length,transformChanges=changes,detailInstances=instances.Count,attachmentErrors,colliders=ts.Sum(t=>t.GetComponents<Collider>().Length),missingScripts=ts.Sum(t=>GameObjectUtility.GetMonoBehavioursWithMissingScriptCount(t.gameObject)),missingMeshes=ts.SelectMany(t=>t.GetComponents<MeshFilter>()).Count(f=>!f.sharedMesh),missingMaterials=ts.SelectMany(t=>t.GetComponents<Renderer>()).Count(r=>r.sharedMaterials.Any(m=>!m||!m.shader)),shaderMessages=messages,shaderErrors=messages.Count(m=>m.severity=="Error"),lodErrors};
 }finally{EditorSceneManager.ClosePreviewScene(preview);}var current=SceneManager.GetActiveScene();var preservation=new{beforeScene=path,afterScene=current.path,beforeDirty=dirty,afterDirty=current.isDirty,beforePlaying=playing,afterPlaying=Application.isPlaying,previewClosed=!preview.IsValid()};File.WriteAllText(Out+"preview_check.json",JsonConvert.SerializeObject(new{validation=result,preservation},Formatting.Indented));return new{validation=result,preservation};}
 static void Shot(string name,Vector3 p,Vector3 target,float fov){var go=new GameObject("TemporaryDetailPreview"){hideFlags=HideFlags.HideAndDontSave};SceneManager.MoveGameObjectToScene(go,preview);var c=go.AddComponent<Camera>();c.scene=preview;c.enabled=false;c.transform.position=p;c.transform.LookAt(target);c.fieldOfView=fov;c.nearClipPlane=.025f;c.farClipPlane=2200;c.useOcclusionCulling=false;c.GetUniversalAdditionalCameraData().renderPostProcessing=false;var rt=new RenderTexture(1600,1000,24){antiAliasing=4};var old=RenderTexture.active;bool async=ShaderUtil.allowAsyncCompilation;Texture2D tex=null;try{ShaderUtil.allowAsyncCompilation=false;c.targetTexture=rt;c.Render();c.Render();RenderTexture.active=rt;tex=new Texture2D(1600,1000,TextureFormat.RGB24,false);tex.ReadPixels(new Rect(0,0,1600,1000),0,0);tex.Apply();File.WriteAllBytes(Out+"after/"+name+".jpg",tex.EncodeToJPG(92));}finally{ShaderUtil.allowAsyncCompilation=async;RenderTexture.active=old;c.targetTexture=null;if(tex)UnityEngine.Object.DestroyImmediate(tex);UnityEngine.Object.DestroyImmediate(rt);UnityEngine.Object.DestroyImmediate(go);}}
}
